  const dotY = tween(t, 7.85, 8, y + point.y * s, 135);
  const radius = key(
    t,
    dotTimes,
    [4, 6, 6, 6.5, 7.5, 9.5, 12, 16, 24, 57, 160, 390],
  );
  return (
    <>
      <Layer
        w={480}
        h={270}
